using CTXD.Server.Data;
using CTXD.Server.Domain;
using Npgsql;
namespace CTXD.Server.Services;

public sealed record KfgzSeasonProvision(int SeasonNo,DateTimeOffset OpensAt,DateTimeOffset FirstBattleAt,DateTimeOffset EndsAt);
public sealed record KfgzRoundProvision(int Round,int WorldId,int Force1,int Force2,DateTimeOffset StartsAt,DateTimeOffset DeadlineAt);
public sealed record KfgzMoveRequest(int GeneralId,int CityId);
public sealed record KfgzRetreatRequest(int[] GeneralIds,int CityId);
public sealed record KfgzResourceView(long Gold,long Copper,long Wood,long Food,long Iron);
public sealed record KfgzGeneralStateView(int GeneralId,int Level,long Forces,int State,int? CityId,long? BattleId);
public sealed record KfgzView(long SeasonId,int SeasonNo,int State,DateTimeOffset NextStateAt,bool Signed,long? CompetitorId,int ForceId,int[] GeneralIds,long Version,KfgzResourceView Resources,KfgzGeneralStateView[] Generals);
public sealed record KfgzCityView(int Id,string Name,int Type,int Terrain,int OwnerSide,int OwnerForce,int State);
public sealed record KfgzRoadView(int Id,int Start,int End,int Length,bool Connected,int NextChangeSeconds);
public sealed record KfgzDeploymentView(long PlayerId,int GeneralId,int CityId,int State,long? BattleId);
public sealed record KfgzBattleView(long Id,long BattleId,int CityId,long AttackerPlayerId,long DefenderPlayerId,int State,long? WinnerPlayerId);
public sealed record KfgzWarView(long RoundId,int Round,int WorldId,int State,DateTimeOffset StartsAt,DateTimeOffset DeadlineAt,int Side,int Force1,int Force2,int? WinnerSide,int? Side1Cities,int? Side2Cities,KfgzCityView[] Cities,KfgzRoadView[] Roads,KfgzDeploymentView[] Deployments,KfgzBattleView[] Battles);
public sealed record KfgzRankEntry(int Rank,long PlayerId,string Name,int ForceId,long CompetitorId,long KillArmy,int OccupyCity,int SoloWins,int Wins,int Losses);

public sealed class KfgzService(GameDb db,GamePushHub push,CanonicalContent content,BattleService battles)
{
 public async Task<long> ProvisionAsync(KfgzSeasonProvision x,CancellationToken ct){if(x.OpensAt>=x.FirstBattleAt||x.FirstBattleAt>=x.EndsAt)throw new GameException("KFGZ_SCHEDULE_INVALID","KFGZ schedule is invalid.");await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var q=new NpgsqlCommand("INSERT INTO kfgz_seasons(season_no,opens_at,first_battle_at,ends_at) VALUES($1,$2,$3,$4) ON CONFLICT(season_no) DO UPDATE SET opens_at=$2,first_battle_at=$3,ends_at=$4,updated_at=now() RETURNING id",c);q.Parameters.AddWithValue(x.SeasonNo);q.Parameters.AddWithValue(x.OpensAt);q.Parameters.AddWithValue(x.FirstBattleAt);q.Parameters.AddWithValue(x.EndsAt);return Convert.ToInt64(await q.ExecuteScalarAsync(ct));}

 public async Task<long> ProvisionRoundAsync(KfgzRoundProvision x,CancellationToken ct)
 {if(x.Round<1||x.Force1 is <1 or >3||x.Force2 is <1 or >3||x.Force1==x.Force2||x.StartsAt>=x.DeadlineAt)throw new GameException("KFGZ_ROUND_INVALID","KFGZ round is invalid.");var cities=content.KfgzWorldCities.Values.Where(v=>v.World==x.WorldId).ToArray();if(cities.Length==0||!cities.Any(v=>v.CityType==1&&v.InitialForce==1)||!cities.Any(v=>v.CityType==1&&v.InitialForce==2))throw new GameException("KFGZ_WORLD_INVALID","Legacy KFGZ world has no two capitals.");await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);long season;DateTimeOffset first,end;await using(var q=new NpgsqlCommand("SELECT id,first_battle_at,ends_at FROM kfgz_seasons ORDER BY season_no DESC LIMIT 1 FOR UPDATE",c,t)){await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFGZ_INACTIVE","No KFGZ season is available.",404);season=r.GetInt64(0);first=r.GetFieldValue<DateTimeOffset>(1);end=r.GetFieldValue<DateTimeOffset>(2);}if(x.StartsAt<first||x.DeadlineAt>end)throw new GameException("KFGZ_ROUND_OUTSIDE_SEASON","KFGZ round must be inside the battle season.");long round;await using(var q=new NpgsqlCommand("INSERT INTO kfgz_rounds(season_id,round_no,world_id,force1,force2,starts_at,deadline_at) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(season_id,round_no,force1,force2) DO UPDATE SET world_id=$3,starts_at=$6,deadline_at=$7 RETURNING id",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(x.Round);q.Parameters.AddWithValue(x.WorldId);q.Parameters.AddWithValue(x.Force1);q.Parameters.AddWithValue(x.Force2);q.Parameters.AddWithValue(x.StartsAt);q.Parameters.AddWithValue(x.DeadlineAt);round=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}foreach(var city in cities){await using var q=new NpgsqlCommand("INSERT INTO kfgz_city_states(round_id,city_id,owner_side) VALUES($1,$2,$3) ON CONFLICT DO NOTHING",c,t);q.Parameters.AddWithValue(round);q.Parameters.AddWithValue(city.CityId);q.Parameters.AddWithValue((short)(city.InitialForce is 1 or 2?city.InitialForce:0));await q.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);return round;}

 public async Task<KfgzView> GetAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);return await ReadAsync(c,player,ct);}
 public async Task<KfgzView> SignupAsync(long player,CancellationToken ct)
 {await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);long season;int state;short force;long gold,copper,wood,food,iron;await using(var q=new NpgsqlCommand("SELECT s.id,s.state,p.force_id,p.sys_gold,r.copper,r.wood,r.food,r.iron FROM kfgz_seasons s JOIN players p ON p.id=$1 JOIN player_resources r ON r.player_id=p.id ORDER BY s.season_no DESC LIMIT 1 FOR UPDATE OF s",c,t)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFGZ_INACTIVE","No KFGZ season is available.",404);season=r.GetInt64(0);state=r.GetInt16(1);force=r.GetInt16(2);gold=r.GetInt64(3);copper=r.GetInt64(4);wood=r.GetInt64(5);food=r.GetInt64(6);iron=r.GetInt64(7);}if(state==0)throw new GameException("KFGZ_SIGNUP_CLOSED","KFGZ signup is not active.",409);if(force is <1 or >3)throw new GameException("KFGZ_FORCE_REQUIRED","Join a legacy nation before KFGZ signup.",403);var ids=new List<int>();await using(var q=new NpgsqlCommand("SELECT general_id FROM player_generals WHERE player_id=$1 AND general_type=2 ORDER BY general_id",c,t)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))ids.Add(r.GetInt32(0));}if(ids.Count==0)throw new GameException("KFGZ_GENERALS_REQUIRED","KFGZ signup requires military generals.");await using(var q=new NpgsqlCommand("INSERT INTO kfgz_signups(season_id,player_id,force_id,general_ids,sys_gold,copper,wood,food,iron) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(season_id,player_id) DO UPDATE SET force_id=$3,general_ids=$4,sys_gold=$5,copper=$6,wood=$7,food=$8,iron=$9,version=kfgz_signups.version+1,synced_at=now()",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(force);q.Parameters.AddWithValue(ids.ToArray());q.Parameters.AddWithValue(gold);q.Parameters.AddWithValue(copper);q.Parameters.AddWithValue(wood);q.Parameters.AddWithValue(food);q.Parameters.AddWithValue(iron);await q.ExecuteNonQueryAsync(ct);}await using(var q=new NpgsqlCommand("INSERT INTO kfgz_player_stats(season_id,player_id) VALUES($1,$2) ON CONFLICT DO NOTHING",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);await q.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);await push.SendAsync(player,"kfgz.updated",new{reason="signup",season},ct);await using var read=await db.DataSource.OpenConnectionAsync(ct);return await ReadAsync(read,player,ct);}

 public async Task<KfgzWarView> WorldAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var m=await RoundAsync(c,t,player,false,ct);await EnsureDeploymentsAsync(c,t,m,player,ct);var view=await ReadWorldAsync(c,t,m,ct);await t.CommitAsync(ct);return view;}

 public async Task<KfgzWarView> MoveAsync(long player,int general,int target,CancellationToken ct)
 {await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var m=await RoundAsync(c,t,player,true,ct);await EnsureDeploymentsAsync(c,t,m,player,ct);int from,state;await using(var q=new NpgsqlCommand("SELECT city_id,state FROM kfgz_deployments WHERE round_id=$1 AND player_id=$2 AND general_id=$3 FOR UPDATE",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(general);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFGZ_GENERAL_INVALID","General is not synchronized into this KFGZ round.",403);from=r.GetInt32(0);state=r.GetInt16(1);}if(state!=1)throw new GameException("KFGZ_GENERAL_BUSY","General is already fighting.",409);if(from==target)throw new GameException("KFGZ_ALREADY_IN_CITY","General is already in this city.");if(!content.KfgzWorldCities.TryGetValue(target,out var city)||city.World!=m.world)throw new GameException("KFGZ_CITY_INVALID","City is not in this KFGZ world.",404);if(city.CityType==1&&city.InitialForce!=m.side)throw new GameException("KFGZ_ENEMY_CAPITAL_FORBIDDEN","Legacy KFGZ movement cannot enter the opposing capital.",409);var road=content.KfgzWorldRoads.Values.FirstOrDefault(v=>v.World==m.world&&(v.From==from&&v.To==target||v.From==target&&v.To==from));if(road is null||!RoadOpen(road,m.starts))throw new GameException("KFGZ_ROAD_CLOSED","No connected legacy KFGZ road reaches this city.",409);int owner;await using(var q=new NpgsqlCommand("SELECT owner_side FROM kfgz_city_states WHERE round_id=$1 AND city_id=$2 FOR UPDATE",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(target);owner=Convert.ToInt16(await q.ExecuteScalarAsync(ct));}long defender=0;var defenders=new List<int>();await using(var q=new NpgsqlCommand("SELECT player_id,array_agg(general_id ORDER BY general_id) FROM kfgz_deployments WHERE round_id=$1 AND city_id=$2 AND state=1 AND player_id<>$3 AND player_id IN(SELECT player_id FROM kfgz_signups WHERE season_id=$4 AND force_id=$5) GROUP BY player_id ORDER BY player_id LIMIT 1",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(target);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(m.season);q.Parameters.AddWithValue(m.side==1?m.force2:m.force1);await using var r=await q.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct)){defender=r.GetInt64(0);defenders.AddRange(r.GetFieldValue<int[]>(1));}}
   if(defender==0){await using(var q=new NpgsqlCommand("UPDATE kfgz_deployments SET city_id=$4,updated_at=now() WHERE round_id=$1 AND player_id=$2 AND general_id=$3",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(general);q.Parameters.AddWithValue(target);await q.ExecuteNonQueryAsync(ct);}if(owner!=m.side){await using var q=new NpgsqlCommand("UPDATE kfgz_city_states SET owner_side=$3,updated_at=now() WHERE round_id=$1 AND city_id=$2;UPDATE kfgz_player_stats SET occupy_city=occupy_city+1,updated_at=now() WHERE season_id=$4 AND player_id=$5",c,t);q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(target);q.Parameters.AddWithValue(m.side);q.Parameters.AddWithValue(m.season);q.Parameters.AddWithValue(player);await q.ExecuteNonQueryAsync(ct);}}
   else{var af=m.side==1?m.force1:m.force2;var df=m.side==1?m.force2:m.force1;long battle;await using(var q=new NpgsqlCommand("INSERT INTO world_battle_handoffs(city_id,attacker_player_id,attacker_general_id,attacker_force_id,defender_force_id,battle_type,result_payload) VALUES($1,$2,$3,$4,$5,18,jsonb_build_object('defenderPlayerId',$6,'attackerGenerals',jsonb_build_array($3),'defenderGenerals',to_jsonb($7::integer[]),'kfgzRoundId',$8,'kfgzSide',$9)) RETURNING id",c,t)){q.Parameters.AddWithValue(target);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(general);q.Parameters.AddWithValue(af);q.Parameters.AddWithValue(df);q.Parameters.AddWithValue(defender);q.Parameters.AddWithValue(defenders.ToArray());q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(m.side);battle=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}long match;await using(var q=new NpgsqlCommand("INSERT INTO kfgz_battles(round_id,city_id,attacker_player_id,defender_player_id,attacker_side,defender_side,battle_id) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING id",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(target);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(defender);q.Parameters.AddWithValue(m.side);q.Parameters.AddWithValue(m.side==1?2:1);q.Parameters.AddWithValue(battle);match=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}await using(var q=new NpgsqlCommand("UPDATE kfgz_deployments SET state=3,battle_id=$4,updated_at=now() WHERE round_id=$1 AND ((player_id=$2 AND general_id=$3) OR (player_id=$5 AND general_id=ANY($6)));UPDATE player_generals SET state=3,updated_at=now() WHERE (player_id=$2 AND general_id=$3) OR (player_id=$5 AND general_id=ANY($6))",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(general);q.Parameters.AddWithValue(battle);q.Parameters.AddWithValue(defender);q.Parameters.AddWithValue(defenders.ToArray());await q.ExecuteNonQueryAsync(ct);}await push.SendAsync(defender,"kfgz.battle",new{matchId=match,battleId=battle,cityId=target,opponent=player},ct);await push.SendAsync(player,"kfgz.battle",new{matchId=match,battleId=battle,cityId=target,opponent=defender},ct);}
   await t.CommitAsync(ct);await push.BroadcastAsync("kfgz.world",new{roundId=m.id,cityId=target},ct);await using var read=await db.DataSource.OpenConnectionAsync(ct);await using var rt=await read.BeginTransactionAsync(ct);var next=await RoundAsync(read,rt,player,false,ct);var view=await ReadWorldAsync(read,rt,next,ct);await rt.CommitAsync(ct);return view;}

 public async Task<KfgzWarView> RetreatAsync(long player,KfgzRetreatRequest x,CancellationToken ct)
 {var ids=(x.GeneralIds??[]).Distinct().ToArray();if(ids.Length==0)throw new GameException("KFGZ_RETREAT_GENERALS_REQUIRED","Select at least one fighting general.");await TickAsync(ct);var finish=new HashSet<long>();await using(var c=await db.DataSource.OpenConnectionAsync(ct)){await using var t=await c.BeginTransactionAsync(ct);var m=await RoundAsync(c,t,player,true,ct);int owner;await using(var q=new NpgsqlCommand("SELECT owner_side FROM kfgz_city_states WHERE round_id=$1 AND city_id=$2 FOR UPDATE",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(x.CityId);owner=Convert.ToInt16(await q.ExecuteScalarAsync(ct)??-1);}if(owner!=m.side)throw new GameException("KFGZ_RETREAT_TARGET_INVALID","Legacy retreat target must be an adjacent city owned by the player's side.",409);await using(var busy=new NpgsqlCommand("SELECT 1 FROM kfgz_battles WHERE round_id=$1 AND city_id=$2 AND state=1",c,t)){busy.Parameters.AddWithValue(m.id);busy.Parameters.AddWithValue(x.CityId);if(await busy.ExecuteScalarAsync(ct)is not null)throw new GameException("KFGZ_RETREAT_TARGET_FIGHTING","Legacy retreat target cannot have an active battle.",409);}foreach(var id in ids){long battle,unit;int from,hp;await using(var q=new NpgsqlCommand("SELECT d.battle_id,d.city_id,u.id,u.hp FROM kfgz_deployments d JOIN battle_units u ON u.battle_id=d.battle_id AND u.player_id=d.player_id AND u.general_id=d.general_id JOIN battles b ON b.id=u.battle_id WHERE d.round_id=$1 AND d.player_id=$2 AND d.general_id=$3 AND d.state=3 AND b.status=0 AND u.hp>0 AND u.detached=false FOR UPDATE OF d,u",c,t)){q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(id);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFGZ_RETREAT_GENERAL_INVALID","General is not active in a KFGZ battle.",409);battle=r.GetInt64(0);from=r.GetInt32(1);unit=r.GetInt64(2);hp=r.GetInt32(3);}var road=content.KfgzWorldRoads.Values.FirstOrDefault(v=>v.World==m.world&&(v.From==from&&v.To==x.CityId||v.From==x.CityId&&v.To==from));if(road is null||!RoadOpen(road,m.starts))throw new GameException("KFGZ_RETREAT_NOT_ADJACENT","Legacy retreat target must be connected to the battle city.",409);var remain=hp*9/10;await using(var q=new NpgsqlCommand("UPDATE battle_units SET hp=$2,detached=true WHERE id=$1;UPDATE kfgz_deployments SET city_id=$4,state=1,battle_id=NULL,updated_at=now() WHERE round_id=$3 AND player_id=$5 AND general_id=$6;UPDATE player_generals SET forces=$2,state=1,updated_at=now() WHERE player_id=$5 AND general_id=$6",c,t)){q.Parameters.AddWithValue(unit);q.Parameters.AddWithValue(remain);q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(x.CityId);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(id);await q.ExecuteNonQueryAsync(ct);}await using(var q=new NpgsqlCommand("SELECT NOT EXISTS(SELECT 1 FROM battle_units WHERE battle_id=$1 AND hp>0 AND detached=false AND side=(SELECT side FROM battle_units WHERE id=$2))",c,t)){q.Parameters.AddWithValue(battle);q.Parameters.AddWithValue(unit);if(Convert.ToBoolean(await q.ExecuteScalarAsync(ct)))finish.Add(battle);}}await t.CommitAsync(ct);}foreach(var battle in finish)await battles.AdvanceAsync(player,battle,ct);await SettleAsync(ct);await push.SendAsync(player,"kfgz.world",new{reason="retreat",x.CityId,generalIds=ids},ct);return await WorldAsync(player,ct);}

 public async Task<KfgzRankEntry[]> RankingAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var q=new NpgsqlCommand("SELECT row_number() OVER(ORDER BY st.kill_army DESC,st.occupy_city DESC,st.solo_wins DESC,st.player_id)::int,st.player_id,COALESCE(p.display_name,''),sg.force_id,sg.competitor_id,st.kill_army,st.occupy_city,st.solo_wins,st.wins,st.losses FROM kfgz_player_stats st JOIN kfgz_signups sg ON sg.season_id=st.season_id AND sg.player_id=st.player_id JOIN players p ON p.id=st.player_id WHERE st.season_id=(SELECT season_id FROM kfgz_signups WHERE player_id=$1 ORDER BY season_id DESC LIMIT 1) ORDER BY 1",c);q.Parameters.AddWithValue(player);var list=new List<KfgzRankEntry>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetInt32(0),r.GetInt64(1),r.GetString(2),r.GetInt16(3),r.GetInt64(4),r.GetInt64(5),r.GetInt32(6),r.GetInt32(7),r.GetInt32(8),r.GetInt32(9)));return list.ToArray();}

 public async Task TickAsync(CancellationToken ct)
 {await using(var c=await db.DataSource.OpenConnectionAsync(ct)){await using var q=new NpgsqlCommand("UPDATE kfgz_seasons SET state=CASE WHEN now()<opens_at OR now()>=ends_at THEN 0 WHEN now()<first_battle_at THEN 3 ELSE 2 END,updated_at=now() WHERE state<>CASE WHEN now()<opens_at OR now()>=ends_at THEN 0 WHEN now()<first_battle_at THEN 3 ELSE 2 END;UPDATE kfgz_rounds SET state=1 WHERE state=0 AND starts_at<=now() AND deadline_at>now()",c);if(await q.ExecuteNonQueryAsync(ct)>0)await push.BroadcastAsync("kfgz.state",new{reason="phase"},ct);}var due=new List<(long battle,long player)>();await using(var c=await db.DataSource.OpenConnectionAsync(ct)){await using var q=new NpgsqlCommand("SELECT b.battle_id,b.attacker_player_id FROM kfgz_battles b JOIN kfgz_rounds r ON r.id=b.round_id WHERE b.state=1 AND r.deadline_at<=now()",c);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))due.Add((r.GetInt64(0),r.GetInt64(1)));}foreach(var x in due)for(var i=0;i<512;i++){var result=await battles.AdvanceAsync(x.player,x.battle,ct);if(result.Status!=0)break;}await SettleAsync(ct);await FinishRoundsAsync(ct);}

 async Task SettleAsync(CancellationToken ct)
 {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var done=new List<(long id,long round,long battle,long season,int city,long attacker,long defender,int aside,int dside,int winnerSide)>();await using(var q=new NpgsqlCommand("SELECT b.id,b.round_id,b.battle_id,r.season_id,b.city_id,b.attacker_player_id,b.defender_player_id,b.attacker_side,b.defender_side,(h.result_payload->>'winnerSide')::int FROM kfgz_battles b JOIN kfgz_rounds r ON r.id=b.round_id JOIN world_battle_handoffs h ON h.id=b.battle_id WHERE b.state=1 AND h.status<>0 FOR UPDATE OF b",c,t)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))done.Add((r.GetInt64(0),r.GetInt64(1),r.GetInt64(2),r.GetInt64(3),r.GetInt32(4),r.GetInt64(5),r.GetInt64(6),r.GetInt16(7),r.GetInt16(8),r.GetInt32(9)));}foreach(var x in done){await using(var ledger=new NpgsqlCommand("INSERT INTO kfgz_settlement_ledger(battle_id) VALUES($1) ON CONFLICT DO NOTHING",c,t)){ledger.Parameters.AddWithValue(x.battle);if(await ledger.ExecuteNonQueryAsync(ct)!=1)continue;}var winner=x.winnerSide==1?x.attacker:x.defender;long ak,dk;await using(var q=new NpgsqlCommand("SELECT COALESCE(sum(CASE WHEN au.player_id=$2 THEN br.defender_damage ELSE 0 END),0)::bigint,COALESCE(sum(CASE WHEN du.player_id=$3 THEN br.attacker_damage ELSE 0 END),0)::bigint FROM battle_rounds br JOIN battle_units au ON au.id=br.attacker_unit_id JOIN battle_units du ON du.id=br.defender_unit_id WHERE br.battle_id=$1",c,t)){q.Parameters.AddWithValue(x.battle);q.Parameters.AddWithValue(x.attacker);q.Parameters.AddWithValue(x.defender);await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);ak=r.GetInt64(0);dk=r.GetInt64(1);}await using(var q=new NpgsqlCommand("UPDATE kfgz_battles SET state=2,winner_player_id=$2,resolved_at=now() WHERE id=$1;UPDATE kfgz_deployments SET state=1,battle_id=NULL,city_id=$4,updated_at=now() WHERE round_id=$3 AND battle_id=$5;UPDATE player_generals pg SET state=1,updated_at=now() FROM kfgz_deployments d WHERE d.round_id=$3 AND d.player_id=pg.player_id AND d.general_id=pg.general_id AND d.city_id=$4 AND d.player_id IN($7,$9);INSERT INTO kfgz_player_stats(season_id,player_id,kill_army,solo_wins,wins,losses) VALUES($6,$7,$8,CASE WHEN $7=$2 THEN 1 ELSE 0 END,CASE WHEN $7=$2 THEN 1 ELSE 0 END,CASE WHEN $7=$2 THEN 0 ELSE 1 END),($6,$9,$10,CASE WHEN $9=$2 THEN 1 ELSE 0 END,CASE WHEN $9=$2 THEN 1 ELSE 0 END,CASE WHEN $9=$2 THEN 0 ELSE 1 END) ON CONFLICT(season_id,player_id) DO UPDATE SET kill_army=kfgz_player_stats.kill_army+excluded.kill_army,solo_wins=kfgz_player_stats.solo_wins+excluded.solo_wins,wins=kfgz_player_stats.wins+excluded.wins,losses=kfgz_player_stats.losses+excluded.losses,updated_at=now()",c,t)){q.Parameters.AddWithValue(x.id);q.Parameters.AddWithValue(winner);q.Parameters.AddWithValue(x.round);q.Parameters.AddWithValue(x.city);q.Parameters.AddWithValue(x.battle);q.Parameters.AddWithValue(x.season);q.Parameters.AddWithValue(x.attacker);q.Parameters.AddWithValue(ak);q.Parameters.AddWithValue(x.defender);q.Parameters.AddWithValue(dk);await q.ExecuteNonQueryAsync(ct);}if(x.winnerSide==1){bool captured;await using(var q=new NpgsqlCommand("UPDATE kfgz_city_states SET owner_side=$3,updated_at=now() WHERE round_id=$1 AND city_id=$2 AND owner_side<>$3 RETURNING 1",c,t)){q.Parameters.AddWithValue(x.round);q.Parameters.AddWithValue(x.city);q.Parameters.AddWithValue(x.aside);captured=await q.ExecuteScalarAsync(ct)is not null;}if(captured)await using(var q=new NpgsqlCommand("UPDATE kfgz_player_stats SET occupy_city=occupy_city+1 WHERE season_id=$1 AND player_id=$2",c,t)){q.Parameters.AddWithValue(x.season);q.Parameters.AddWithValue(x.attacker);await q.ExecuteNonQueryAsync(ct);}}}await t.CommitAsync(ct);foreach(var x in done){await push.SendAsync(x.attacker,"kfgz.result",new{battleId=x.battle,winnerSide=x.winnerSide},ct);await push.SendAsync(x.defender,"kfgz.result",new{battleId=x.battle,winnerSide=x.winnerSide},ct);}}

 async Task FinishRoundsAsync(CancellationToken ct)
 {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var ended=new List<(long id,int c1,int c2,int winner)>();await using(var q=new NpgsqlCommand("SELECT r.id,count(*) FILTER(WHERE c.owner_side=1)::int,count(*) FILTER(WHERE c.owner_side=2)::int FROM kfgz_rounds r JOIN kfgz_city_states c ON c.round_id=r.id WHERE r.state=1 AND r.deadline_at<=now() AND NOT EXISTS(SELECT 1 FROM kfgz_battles b WHERE b.round_id=r.id AND b.state=1) GROUP BY r.id FOR UPDATE OF r",c,t)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct)){var c1=r.GetInt32(1);var c2=r.GetInt32(2);ended.Add((r.GetInt64(0),c1,c2,c1==c2?0:c1>c2?1:2));}}foreach(var x in ended){await using var q=new NpgsqlCommand("UPDATE kfgz_rounds SET state=2,winner_side=$2,side1_cities=$3,side2_cities=$4,resolved_at=now() WHERE id=$1;UPDATE kfgz_deployments SET state=2,updated_at=now() WHERE round_id=$1",c,t);q.Parameters.AddWithValue(x.id);q.Parameters.AddWithValue(x.winner);q.Parameters.AddWithValue(x.c1);q.Parameters.AddWithValue(x.c2);await q.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);foreach(var x in ended)await push.BroadcastAsync("kfgz.round.result",new{roundId=x.id,winnerSide=x.winner,side1Cities=x.c1,side2Cities=x.c2},ct);}

 async Task EnsureDeploymentsAsync(NpgsqlConnection c,NpgsqlTransaction t,(long id,long season,int round,int world,int state,DateTimeOffset starts,DateTimeOffset deadline,int force1,int force2,int side) m,long player,CancellationToken ct){var capital=content.KfgzWorldCities.Values.Single(v=>v.World==m.world&&v.CityType==1&&v.InitialForce==m.side).CityId;await using var q=new NpgsqlCommand("INSERT INTO kfgz_deployments(round_id,player_id,general_id,city_id) SELECT $1,$2,unnest(general_ids),$3 FROM kfgz_signups WHERE season_id=$4 AND player_id=$2 ON CONFLICT DO NOTHING",c,t);q.Parameters.AddWithValue(m.id);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(capital);q.Parameters.AddWithValue(m.season);await q.ExecuteNonQueryAsync(ct);}
 async Task<(long id,long season,int round,int world,int state,DateTimeOffset starts,DateTimeOffset deadline,int force1,int force2,int side)> RoundAsync(NpgsqlConnection c,NpgsqlTransaction t,long player,bool active,CancellationToken ct){await using var q=new NpgsqlCommand("SELECT r.id,r.season_id,r.round_no,r.world_id,r.state,r.starts_at,r.deadline_at,r.force1,r.force2,CASE WHEN s.force_id=r.force1 THEN 1 ELSE 2 END FROM kfgz_rounds r JOIN kfgz_signups s ON s.season_id=r.season_id AND s.player_id=$1 AND (s.force_id=r.force1 OR s.force_id=r.force2) WHERE (NOT $2 OR r.state=1) ORDER BY r.round_no DESC LIMIT 1",c,t);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(active);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFGZ_ROUND_UNAVAILABLE","Player has no KFGZ war round.",404);return(r.GetInt64(0),r.GetInt64(1),r.GetInt32(2),r.GetInt32(3),r.GetInt16(4),r.GetFieldValue<DateTimeOffset>(5),r.GetFieldValue<DateTimeOffset>(6),r.GetInt16(7),r.GetInt16(8),r.GetInt32(9));}
 async Task<KfgzWarView> ReadWorldAsync(NpgsqlConnection c,NpgsqlTransaction t,(long id,long season,int round,int world,int state,DateTimeOffset starts,DateTimeOffset deadline,int force1,int force2,int side) m,CancellationToken ct)
 {var runtime=new Dictionary<int,(int owner,int state)>();await using(var q=new NpgsqlCommand("SELECT city_id,owner_side,state FROM kfgz_city_states WHERE round_id=$1",c,t)){q.Parameters.AddWithValue(m.id);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))runtime[r.GetInt32(0)]=(r.GetInt16(1),r.GetInt16(2));}var cities=content.KfgzWorldCities.Values.Where(v=>v.World==m.world).OrderBy(v=>v.CityId).Select(v=>{var x=runtime[v.CityId];return new KfgzCityView(v.CityId,v.Name,v.CityType,v.TerrainId,x.owner,x.owner==1?m.force1:x.owner==2?m.force2:0,x.state);}).ToArray();var roads=content.KfgzWorldRoads.Values.Where(v=>v.World==m.world).OrderBy(v=>v.RoadId).Select(v=>new KfgzRoadView(v.RoadId,v.From,v.To,v.Distance,RoadOpen(v,m.starts),NextRoadChange(v,m.starts))).ToArray();var ds=new List<KfgzDeploymentView>();await using(var q=new NpgsqlCommand("SELECT player_id,general_id,city_id,state,battle_id FROM kfgz_deployments WHERE round_id=$1 ORDER BY player_id,general_id",c,t)){q.Parameters.AddWithValue(m.id);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))ds.Add(new(r.GetInt64(0),r.GetInt32(1),r.GetInt32(2),r.GetInt16(3),r.IsDBNull(4)?null:r.GetInt64(4)));}var bs=new List<KfgzBattleView>();await using(var q=new NpgsqlCommand("SELECT id,battle_id,city_id,attacker_player_id,defender_player_id,state,winner_player_id FROM kfgz_battles WHERE round_id=$1 ORDER BY id",c,t)){q.Parameters.AddWithValue(m.id);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))bs.Add(new(r.GetInt64(0),r.GetInt64(1),r.GetInt32(2),r.GetInt64(3),r.GetInt64(4),r.GetInt16(5),r.IsDBNull(6)?null:r.GetInt64(6)));}int? winner=null,c1=null,c2=null;await using(var q=new NpgsqlCommand("SELECT winner_side,side1_cities,side2_cities FROM kfgz_rounds WHERE id=$1",c,t)){q.Parameters.AddWithValue(m.id);await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);winner=r.IsDBNull(0)?null:r.GetInt16(0);c1=r.IsDBNull(1)?null:r.GetInt32(1);c2=r.IsDBNull(2)?null:r.GetInt32(2);}return new(m.id,m.round,m.world,m.state,m.starts,m.deadline,m.side,m.force1,m.force2,winner,c1,c2,cities,roads,ds.ToArray(),bs.ToArray());}

 static bool RoadOpen(KfgzWorldRoadDefinition r,DateTimeOffset starts)=>r.RoadType!=1||DynamicRoad(r,starts).open;
 static int NextRoadChange(KfgzWorldRoadDefinition r,DateTimeOffset starts)=>r.RoadType!=1?0:DynamicRoad(r,starts).seconds;
 static (bool open,int seconds) DynamicRoad(KfgzWorldRoadDefinition r,DateTimeOffset starts){var elapsed=Math.Max(0,(int)(DateTimeOffset.UtcNow-starts).TotalSeconds);var first=Math.Max(1,r.Disconnect-r.Disconnect/2)*60;if(elapsed<first)return(false,first-elapsed);elapsed-=first;var open=true;while(true){var span=Math.Max(1,open?r.Connect:r.Disconnect)*60;if(elapsed<span)return(open,span-elapsed);elapsed-=span;open=!open;}}
 static async Task<KfgzView> ReadAsync(NpgsqlConnection c,long player,CancellationToken ct)
 {long season;int no,state,force;DateTimeOffset next;bool signed;long? competitor;int[] ids;long version,gold,copper,wood,food,iron;await using(var q=new NpgsqlCommand("SELECT s.id,s.season_no,s.state,CASE WHEN s.state=0 AND now()<s.opens_at THEN s.opens_at WHEN s.state=3 THEN s.first_battle_at ELSE s.ends_at END,g.competitor_id,COALESCE(g.force_id,p.force_id),g.general_ids,COALESCE(g.version,0),p.sys_gold+p.user_gold,pr.copper,pr.wood,pr.food,pr.iron FROM kfgz_seasons s JOIN players p ON p.id=$1 JOIN player_resources pr ON pr.player_id=p.id LEFT JOIN kfgz_signups g ON g.season_id=s.id AND g.player_id=p.id ORDER BY s.season_no DESC LIMIT 1",c)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFGZ_INACTIVE","No KFGZ season is available.",404);season=r.GetInt64(0);no=r.GetInt32(1);state=r.GetInt16(2);next=r.GetFieldValue<DateTimeOffset>(3);signed=!r.IsDBNull(4);competitor=signed?r.GetInt64(4):null;force=r.GetInt16(5);ids=signed?r.GetFieldValue<int[]>(6):Array.Empty<int>();version=r.GetInt64(7);gold=r.GetInt64(8);copper=r.GetInt64(9);wood=r.GetInt64(10);food=r.GetInt64(11);iron=r.GetInt64(12);}var generals=new List<KfgzGeneralStateView>();if(signed)await using(var q=new NpgsqlCommand("SELECT pg.general_id,pg.level,pg.forces,COALESCE(d.state,pg.state),d.city_id,d.battle_id FROM player_generals pg LEFT JOIN LATERAL(SELECT d.state,d.city_id,d.battle_id FROM kfgz_deployments d JOIN kfgz_rounds r ON r.id=d.round_id WHERE r.season_id=$3 AND d.player_id=pg.player_id AND d.general_id=pg.general_id ORDER BY r.round_no DESC LIMIT 1)d ON true WHERE pg.player_id=$1 AND pg.general_id=ANY($2) ORDER BY pg.general_id",c)){q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(ids);q.Parameters.AddWithValue(season);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))generals.Add(new(r.GetInt32(0),r.GetInt32(1),r.GetInt64(2),r.GetInt16(3),r.IsDBNull(4)?null:r.GetInt32(4),r.IsDBNull(5)?null:r.GetInt64(5)));}return new(season,no,state,next,signed,competitor,force,ids,version,new(gold,copper,wood,food,iron),generals.ToArray());}
}
